169: function setup({
170: 	getSocketToken,
171: 	createSocket,
172: }: {
173: 	getSocketToken: () => Promise<string | null>;
174: 	createSocket: SocketFactory;
175: }) {
176: 	const invalidate = vi.fn();
177: 	const handle = connectNotificationRealtime({
178: 		socketUrl: SOCKET_URL,
179: 		getSocketToken,
180: 		invalidate,
181: 		createSocket,
182: 	});
183: 	return { invalidate, handle };
184: }
